import { HttpStatus } from '@nestjs/common';
import { AuthErrorCode, AuthException, authError, formatGraphQLError } from './auth-errors';

describe('authentication GraphQL errors', () => {
	it.each([
		[AuthErrorCode.INVALID_CREDENTIALS, HttpStatus.UNAUTHORIZED],
		[AuthErrorCode.EMAIL_ALREADY_EXISTS, HttpStatus.CONFLICT],
		[AuthErrorCode.PASSWORD_MISMATCH, HttpStatus.BAD_REQUEST],
		[AuthErrorCode.INVALID_EMAIL, HttpStatus.BAD_REQUEST],
		[AuthErrorCode.ACCOUNT_BLOCKED, HttpStatus.UNAUTHORIZED],
		[AuthErrorCode.ACCOUNT_DELETED, HttpStatus.UNAUTHORIZED],
		[AuthErrorCode.UNAUTHENTICATED, HttpStatus.UNAUTHORIZED],
		[AuthErrorCode.INVALID_TOKEN, HttpStatus.UNAUTHORIZED],
		[AuthErrorCode.FORBIDDEN, HttpStatus.FORBIDDEN],
		[AuthErrorCode.GOOGLE_INVALID, HttpStatus.UNAUTHORIZED],
		[AuthErrorCode.GOOGLE_ACCOUNT_CONFLICT, HttpStatus.CONFLICT],
		[AuthErrorCode.CONFIGURATION_ERROR, HttpStatus.INTERNAL_SERVER_ERROR],
	])('preserves %s and its HTTP status', (code, status) => {
		const exception = authError(code);
		const graphQLError = formatGraphQLError({ message: exception.message, extensions: { code: 'INTERNAL_SERVER_ERROR' } }, { originalError: exception });
		expect(exception).toBeInstanceOf(AuthException);
		expect(exception.getStatus()).toBe(status);
		expect(graphQLError.extensions.code).toBe(code);
		expect(graphQLError.message).not.toContain('JWT_SECRET');
		expect(JSON.stringify(graphQLError)).not.toMatch(/secret-password|secret-hash|sensitive-google-token|Bearer\s+sensitive-jwt|mongodb:\/\/private|private\\auth\.ts|secret stack/i);
	});

	it('does not expose internal server error messages or exception details', () => {
		const result = formatGraphQLError({
			message: 'MongoServerError: password hash at C:\\private\\auth.ts',
			extensions: { code: 'INTERNAL_SERVER_ERROR', stacktrace: ['secret stack'] },
		});
		expect(result).toEqual({ message: 'Internal server error', extensions: { code: 'INTERNAL_SERVER_ERROR' } });
	});
});

import { HttpException, HttpStatus, Logger } from '@nestjs/common';

export enum AuthErrorCode {
	INVALID_CREDENTIALS = 'AUTH_INVALID_CREDENTIALS',
	EMAIL_ALREADY_EXISTS = 'AUTH_EMAIL_ALREADY_EXISTS',
	PASSWORD_MISMATCH = 'AUTH_PASSWORD_MISMATCH',
	INVALID_EMAIL = 'AUTH_INVALID_EMAIL',
	ACCOUNT_BLOCKED = 'AUTH_ACCOUNT_BLOCKED',
	ACCOUNT_DELETED = 'AUTH_ACCOUNT_DELETED',
	UNAUTHENTICATED = 'AUTH_UNAUTHENTICATED',
	INVALID_TOKEN = 'AUTH_INVALID_TOKEN',
	FORBIDDEN = 'AUTH_FORBIDDEN',
	GOOGLE_INVALID = 'AUTH_GOOGLE_INVALID',
	GOOGLE_ACCOUNT_CONFLICT = 'AUTH_GOOGLE_ACCOUNT_CONFLICT',
	CONFIGURATION_ERROR = 'AUTH_CONFIGURATION_ERROR',
}

const definitions: Record<AuthErrorCode, { status: HttpStatus; message: string }> = {
	[AuthErrorCode.INVALID_CREDENTIALS]: { status: HttpStatus.UNAUTHORIZED, message: 'Invalid email or password.' },
	[AuthErrorCode.EMAIL_ALREADY_EXISTS]: { status: HttpStatus.CONFLICT, message: 'An account with this email already exists.' },
	[AuthErrorCode.PASSWORD_MISMATCH]: { status: HttpStatus.BAD_REQUEST, message: 'Passwords do not match.' },
	[AuthErrorCode.INVALID_EMAIL]: { status: HttpStatus.BAD_REQUEST, message: 'Enter a valid email address.' },
	[AuthErrorCode.ACCOUNT_BLOCKED]: { status: HttpStatus.UNAUTHORIZED, message: 'This account has been blocked.' },
	[AuthErrorCode.ACCOUNT_DELETED]: { status: HttpStatus.UNAUTHORIZED, message: 'This account is no longer available.' },
	[AuthErrorCode.UNAUTHENTICATED]: { status: HttpStatus.UNAUTHORIZED, message: 'Authentication is required.' },
	[AuthErrorCode.INVALID_TOKEN]: { status: HttpStatus.UNAUTHORIZED, message: 'Authentication token is invalid or expired.' },
	[AuthErrorCode.FORBIDDEN]: { status: HttpStatus.FORBIDDEN, message: 'You do not have permission to perform this action.' },
	[AuthErrorCode.GOOGLE_INVALID]: { status: HttpStatus.UNAUTHORIZED, message: 'Google authentication failed.' },
	[AuthErrorCode.GOOGLE_ACCOUNT_CONFLICT]: { status: HttpStatus.CONFLICT, message: 'This Google account cannot be linked to the existing account automatically.' },
	[AuthErrorCode.CONFIGURATION_ERROR]: { status: HttpStatus.INTERNAL_SERVER_ERROR, message: 'Authentication service is temporarily unavailable.' },
};

export class AuthException extends HttpException {
	readonly authErrorCode: AuthErrorCode;

	constructor(code: AuthErrorCode) {
		const definition = definitions[code];
		super({ statusCode: definition.status, message: definition.message, authErrorCode: code }, definition.status);
		this.authErrorCode = code;
	}
}

export function authError(code: AuthErrorCode): AuthException {
	return new AuthException(code);
}

export function logAuthConfigurationIssue(variable: 'JWT_SECRET' | 'GOOGLE_CLIENT_ID'): void {
	new Logger('Authentication').error(`Authentication configuration missing: ${variable}`);
}

export function formatGraphQLError(error: any, rawError?: any): { message: string; extensions: Record<string, unknown> } {
	const source = rawError ?? error;
	const original = source?.originalError ?? error?.originalError ?? error?.extensions?.originalError ?? source;
	let response: any;
	try {
		response = typeof original?.getResponse === 'function' ? original.getResponse() : original?.response;
	} catch {
		response = undefined;
	}
	const authCode = response?.authErrorCode ?? error?.extensions?.response?.authErrorCode ?? original?.authErrorCode ?? error?.extensions?.authErrorCode;
	if (Object.values(AuthErrorCode).includes(authCode)) {
		return { message: definitions[authCode as AuthErrorCode].message, extensions: { code: authCode } };
	}

	const code = error?.extensions?.code ?? 'INTERNAL_SERVER_ERROR';
	if (code === 'RATE_LIMITED' || code === 'RATE_LIMIT_UNAVAILABLE') {
		return { message: error.message, extensions: { code, retryAfterSeconds: error.extensions.retryAfterSeconds } };
	}
	const statusCode = response?.statusCode;
	const internal = code === 'INTERNAL_SERVER_ERROR' || statusCode >= 500;
	const message = internal ? 'Internal server error' : safeMessage(response?.message) ?? safeMessage(error?.message) ?? 'Request failed';
	return { message, extensions: { code } };
}

function safeMessage(value: unknown): string | undefined {
	if (typeof value === 'string') return value;
	if (Array.isArray(value) && value.every((item) => typeof item === 'string')) return value.join(', ');
	return undefined;
}

import { RegisterInput } from './auth.dto';
import { AuthErrorCode } from './auth-errors';
import { AuthValidationPipe } from './auth-validation.pipe';

describe('AuthValidationPipe', () => {
	const pipe = new AuthValidationPipe();
	const metadata = { type: 'body' as const, metatype: RegisterInput, data: undefined };

	it('maps invalid auth email format to AUTH_INVALID_EMAIL without echoing submitted secrets', async () => {
		await expect(pipe.transform({ email: 'invalid', password: 'sensitive-password', confirmPassword: 'sensitive-password' }, metadata)).rejects.toMatchObject({
			authErrorCode: AuthErrorCode.INVALID_EMAIL,
			message: 'Enter a valid email address.',
		});
	});

	it.each(['ADMIN', 'OWNER', 'CREW'])('rejects client-supplied %s role fields', async (role) => {
		await expect(pipe.transform({ email: 'sailor@example.com', password: 'sensitive-password', confirmPassword: 'sensitive-password', role }, metadata)).rejects.toBeDefined();
	});
});

import { BadRequestException, Injectable, ValidationPipe } from '@nestjs/common';
import { AuthErrorCode, authError } from './auth-errors';

@Injectable()
export class AuthValidationPipe extends ValidationPipe {
	constructor() {
		super({
			transform: true,
			whitelist: true,
			forbidNonWhitelisted: true,
			validationError: { target: false, value: false },
		exceptionFactory: (errors) => {
				if (errors.some((error) => error.property === 'email' && error.constraints?.isEmail)) {
					return authError(AuthErrorCode.INVALID_EMAIL);
				}
				return new BadRequestException(errors.map((error) => Object.values(error.constraints ?? {})).flat());
			},
		});
	}
}

import { Field, ID, InputType, ObjectType } from '@nestjs/graphql';
import { Transform } from 'class-transformer';
import { IsEmail, IsString, MinLength } from 'class-validator';
import { MemberRole, MemberStatus } from '../../libs/enums/member.enum';

@InputType()
export class RegisterInput {
	@Field()
	@Transform(({ value }) => (typeof value === 'string' ? value.trim() : value))
	@IsEmail()
	email: string;

	@Field()
	@IsString()
	@MinLength(1)
	password: string;

	@Field()
	@IsString()
	@MinLength(1)
	confirmPassword: string;
}

@InputType()
export class LoginInput {
	@Field()
	@Transform(({ value }) => (typeof value === 'string' ? value.trim() : value))
	@IsEmail()
	email: string;

	@Field()
	@IsString()
	@MinLength(1)
	password: string;
}

@InputType()
export class GoogleLoginInput {
	@Field()
	@IsString()
	@MinLength(1)
	credential: string;
}

@ObjectType()
export class Member {
	@Field(() => ID)
	_id: string;

	@Field()
	email: string;

	@Field(() => String, { nullable: true })
	googleId?: string | null;

	@Field(() => MemberRole)
	role: MemberRole;

	@Field(() => MemberStatus)
	status: MemberStatus;

	@Field(() => Date)
	createdAt: Date;

	@Field(() => Date)
	updatedAt: Date;
}

@ObjectType()
export class AuthResponse {
	@Field()
	accessToken: string;

	@Field(() => Member)
	member: Member;
}

