	it.each([
		'name',
		'country',
		'city',
		'addressLine1',
		'email',
		'slug',
		'status',
		'timezone',
		'featured',
		'sortOrder',
		'images',
	])('rejects explicit mutation null for %s', async (field) => {
		await expect(service.update({ _id: id, [field]: null } as any)).rejects.toBeInstanceOf(BadRequestException);
	});
	it('checks duplicate slugs across statuses', async () => {
		model.exists.mockResolvedValue({ _id: id });
		await expect(service.create(valid)).rejects.toThrow('slug already exists');
		await expect(service.update({ _id: id, slug: 'duplicate' })).rejects.toThrow('slug already exists');
	});
	it('maps unique-index write races on create and update', async () => {
		model.create.mockRejectedValue({ code: 11000 });
		await expect(service.create(valid)).rejects.toThrow('slug already exists');
		model.findByIdAndUpdate.mockReturnValue({
			exec: async () => {
				throw { code: 11000 };
			},
		});
		await expect(service.update({ _id: id, slug: 'new' })).rejects.toThrow('slug already exists');
	});
	it('preserves omitted fields and public slug on name change', async () => {
		await service.update({ _id: id, name: ' New ', featured: undefined });
		expect(model.findByIdAndUpdate).toHaveBeenCalledWith(
			id,
			{ $set: { name: 'New' } },
			{ new: true, runValidators: true },
		);
	});
	it('normalizes explicit slug updates excluding the current record', async () => {
		await service.update({ _id: id, slug: 'NEW Slug', featured: false, sortOrder: 0, images: [], businessHours: [] });
		expect(model.exists).toHaveBeenLastCalledWith({ slug: 'new-slug', _id: { $ne: id } });
		expect(model.findByIdAndUpdate.mock.calls[0][1].$set).toMatchObject({
			slug: 'new-slug',
			featured: false,
			sortOrder: 0,
			images: [],
			businessHours: [],
		});
	});
	it('rejects missing updates and concurrent removal', async () => {
		model.exists.mockResolvedValueOnce(null);
		await expect(service.update({ _id: id })).rejects.toBeInstanceOf(NotFoundException);
		model.findByIdAndUpdate.mockReturnValue({ exec: async () => null });
		await expect(service.update({ _id: id })).rejects.toBeInstanceOf(NotFoundException);
	});
	it('enforces publication for detail even when no record is visible', async () => {
		await expect(service.getBySlug(' TEST ')).rejects.toBeInstanceOf(NotFoundException);
		expect(model.findOne).toHaveBeenCalledWith({ slug: 'test', status: 'PUBLISHED' });
	});
	it('enforces publication and featured independently of client filters', async () => {
		await service.catalog({ filter: { status: 'ARCHIVED', featured: false } } as any, true);
		expect(model.aggregate.mock.calls[0][0][0].$match).toEqual({ status: 'PUBLISHED', featured: true });
	});
	it('permits admin status filtering and escapes literal regex characters', async () => {
		await service.getForAdmin({ filter: { status: 'DRAFT', country: 'A+B', city: 'C.(D)', search: '.*' } } as any);
		const match = model.aggregate.mock.calls[0][0][0].$match;
		expect(match.status).toBe('DRAFT');
		expect(match.country.test('A+B')).toBe(true);
		expect(match.country.test('AAAB')).toBe(false);
		expect(match.city.test('C.(D)')).toBe(true);
		expect(match.$or[0].name.test('anything')).toBe(false);
		expect(match.$or[0].name.test('literal .*')).toBe(true);
	});
	it.each([
		[OfficeSortBy.FEATURED, { featured: -1, sortOrder: 1, name: 1, _id: 1 }],
		[OfficeSortBy.SORT_ORDER, { sortOrder: 1, name: 1, _id: 1 }],
		[OfficeSortBy.NAME_ASC, { name: 1, _id: 1 }],
		[OfficeSortBy.NAME_DESC, { name: -1, _id: 1 }],
		[OfficeSortBy.NEWEST, { createdAt: -1, _id: -1 }],
	])('uses deterministic MongoDB %s sorting', async (sortBy, expected) => {
		await service.catalog({ sortBy } as any);
		expect(model.aggregate.mock.calls[0][0][1].$sort).toEqual(expected);
	});
	it('returns defaults and MongoDB skip/limit with full count', async () => {
		expect(await service.catalog({} as any)).toEqual({ list: [], total: 41, page: 1, limit: 20, totalPages: 3 });
		expect(await service.catalog({ page: 3, limit: 10 } as any)).toMatchObject({ page: 3, limit: 10, totalPages: 5 });
		expect(model.aggregate.mock.calls[1][0][2].$facet.list).toEqual([{ $skip: 20 }, { $limit: 10 }]);
		model.aggregate.mockResolvedValue([]);
		expect(await service.catalog({ limit: 50 } as any)).toMatchObject({ total: 0, totalPages: 0 });
	});
	it.each([{ page: 0 }, { page: 1.5 }, { limit: 0 }, { limit: 51 }, { limit: 1.5 }, { sortBy: 'BAD' }])(
		'rejects invalid pagination/sort %j',
		async (input) => {
			await expect(service.catalog(input as any)).rejects.toBeInstanceOf(BadRequestException);
			expect(model.aggregate).not.toHaveBeenCalled();
		},
	);
	it('validates optional broker reference existence regardless of status', async () => {
		await expect(service.validateId(id)).resolves.toBeUndefined();
		await expect(service.validateId('invalid')).rejects.toThrow('Invalid office ID');
		model.exists.mockResolvedValue(null);
		await expect(service.validateId(id)).rejects.toThrow('Office not found');
	});
});

import { Types } from 'mongoose';
import { YachtService } from './yacht.service';
import { YachtResolver } from './yacht.resolver';
import { YachtListingMode } from '../../libs/enums/yacht.enum';

describe('Yacht explicit destination tags', () => {
	const id = '507f1f77bcf86cd799439011';
	const other = '507f1f77bcf86cd799439012';
	const valid = {
		name: 'Example Yacht',
		location: 'Nice',
		country: 'France',
		brokerId: id,
		listingModes: [YachtListingMode.SALE],
	};
	let service: YachtService;
	let model: any;
	let destinations: any;
	beforeEach(() => {
		model = {
			create: jest.fn(async (fields) => fields),
			aggregate: jest.fn().mockResolvedValue([{ list: [], meta: [] }]),
			findById: jest.fn(() => ({ lean: () => ({ exec: async () => ({ ...valid, destinationIds: [id] }) }) })),
			findByIdAndUpdate: jest.fn((_id, update) => ({ exec: async () => ({ ...valid, _id, ...update.$set }) })),
		};
		destinations = { validateIds: jest.fn() };
		service = new YachtService(model, { getById: jest.fn() } as never, destinations);
	});
	it('keeps existing yachts valid without tags or a destination lookup', async () => {
		await service.create(valid);
		expect(destinations.validateIds).not.toHaveBeenCalled();
		expect(model.create.mock.calls[0][0]).toMatchObject({ location: 'Nice', country: 'France' });
	});
	it.each([{ destinationIds: [id] }, { destinationIds: [id, other] }, { destinationIds: [] }])(
		'validates explicitly supplied tags %j',
		async ({ destinationIds }) => {
			await service.create({ ...valid, destinationIds });
			expect(destinations.validateIds).toHaveBeenCalledWith(destinationIds);
		},
	);
	it('preserves omitted tags on partial updates', async () => {
		await service.update({ _id: id, name: 'Updated Yacht' });
		expect(destinations.validateIds).not.toHaveBeenCalled();
		expect(model.findByIdAndUpdate.mock.calls[0][1].$set).toEqual({ name: 'Updated Yacht' });
	});
	it('validates replacement tags and supports clearing with an empty array', async () => {
		await service.update({ _id: id, destinationIds: [other] });
		expect(destinations.validateIds).toHaveBeenCalledWith([other]);
		await service.update({ _id: id, destinationIds: [] });
		expect(model.findByIdAndUpdate.mock.calls[1][1].$set).toEqual({ destinationIds: [] });
	});
	it.each([{ destinationIds: ['bad'] }, { destinationIds: [id, id] }, { destinationIds: null }])(
		'rejects invalid tags %j before create or update',
		async (patch) => {
			await expect(service.create({ ...valid, ...patch } as never)).rejects.toThrow('Invalid yacht input');
			await expect(service.update({ _id: id, ...patch } as never)).rejects.toThrow('Invalid yacht input');
			expect(model.create).not.toHaveBeenCalled();
			expect(model.findByIdAndUpdate).not.toHaveBeenCalled();
		},
	);
	it('rejects nonexistent references before writes', async () => {
		destinations.validateIds.mockRejectedValue(new Error('Destination not found'));
		await expect(service.create({ ...valid, destinationIds: [id] })).rejects.toThrow('Destination not found');
		await expect(service.update({ _id: id, destinationIds: [id] })).rejects.toThrow('Destination not found');
		expect(model.create).not.toHaveBeenCalled();
		expect(model.findByIdAndUpdate).not.toHaveBeenCalled();
	});
	it('uses BSON scalar membership with existing filters, no descendant expansion', async () => {
		await service.catalog({
			filter: { destinationId: id, location: 'Nice', country: 'France', mode: YachtListingMode.SALE },
		} as never);
		expect(model.aggregate.mock.calls[0][0][0].$match).toEqual({
			status: 'PUBLISHED',
			destinationIds: new Types.ObjectId(id),
			listingModes: 'SALE',
			location: /Nice/i,
			country: /^France$/i,
		});
		expect(destinations.validateIds).not.toHaveBeenCalled();
	});
	it('applies membership on staff and featured paths', async () => {
		await service.getForStaff({ filter: { destinationId: other } } as never);
		await service.catalog({ filter: { destinationId: other } } as never, true);
		expect(model.aggregate.mock.calls[0][0][0].$match).toEqual({ destinationIds: new Types.ObjectId(other) });
		expect(model.aggregate.mock.calls[1][0][0].$match).toEqual({
			status: 'PUBLISHED',
			destinationIds: new Types.ObjectId(other),
			featured: true,
		});
	});
	it('rejects invalid destination filter IDs before aggregation', async () => {
		await expect(service.catalog({ filter: { destinationId: 'bad' } } as never)).rejects.toThrow('Invalid yacht query');
		expect(model.aggregate).not.toHaveBeenCalled();
	});
	it('presents empty tags for older records without rewriting persistence', () => {
		const resolver = new YachtResolver(service, {} as never);
		expect(resolver.resolveDestinationIds(valid as never)).toEqual([]);
		expect(resolver.resolveDestinationIds({ destinationIds: [id] } as never)).toEqual([id]);
	});
});

﻿import { BadRequestException } from '@nestjs/common';
import { normalizeYachtPricingInput } from './yacht-pricing';
const { planYachtMigration } = require('../../../../../scripts/migrate-legacy-yachts');

describe('Yacht pricing input boundary', () => {
	it.each([
		[{ charterPrice: 100 }, { charterPrice: 100 }],
		[{ charterRate: 100 }, { charterPrice: 100 }],
		[{ charterPrice: 100, charterRate: 100 }, { charterPrice: 100 }],
		[{ charterRate: 0 }, { charterPrice: 0 }],
	])('normalizes %j to one canonical field', (input, expected) => {
		expect(normalizeYachtPricingInput(input)).toEqual(expected);
	});
	it('rejects conflicting aliases', () => {
		expect(() => normalizeYachtPricingInput({ charterPrice: 100, charterRate: 200 })).toThrow(BadRequestException);
	});
	it('preserves other fields and does not add an omitted update price', () => {
		const input = { name: 'Aurelis', charterRate: 100 };
		expect(normalizeYachtPricingInput(input)).toEqual({ name: 'Aurelis', charterPrice: 100 });
		expect(input).toHaveProperty('charterRate', 100);
		expect(normalizeYachtPricingInput({ name: 'Aurelis' } as typeof input)).toEqual({ name: 'Aurelis' });
	});
});

describe('Legacy yacht migration planning (no database access)', () => {
	it('maps and deduplicates modes and copies only absent canonical prices', () => {
		const plan = planYachtMigration({ _id: 'yacht', listingModes: ['SALES', 'SALE', 'CHARTER'], charterRate: 0 });
		expect(plan.update).toEqual({
			$set: { listingModes: ['SALE', 'CHARTER'], charterPrice: 0 },
			$unset: { charterRate: '' },
		});
