			{ ...yachtBase, _id: id(21), destinationIds: [new Types.ObjectId(id(1)), new Types.ObjectId(id(2))] },
			{ ...yachtBase, _id: id(22) },
			{ ...yachtBase, _id: id(23), destinationIds: [new Types.ObjectId(id(2))], status: 'DRAFT' },
